import{at as e,it as t,n,vt as r}from"./chunks/framework.DkF-bNzI.js";var i=JSON.parse(`{"title":"数据库配置","description":"","frontmatter":{},"headers":[],"relativePath":"backend/database.md","filePath":"backend/database.md","lastUpdated":1794885321000}`),a={name:`backend/database.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="数据库配置" tabindex="-1">数据库配置 <a class="header-anchor" href="#数据库配置" aria-label="Permalink to “数据库配置”">​</a></h1><p>本页说明数据库连接、从库与 SQL 日志、多库落点、数据访问方式与建表策略，适用于后端开发者与部署人员。</p><p>数据层是 SqlSugar（框架 <code>Persistence.SqlSugar</code> 的「方式一」：应用提供连接配置回调）。支持 PostgreSQL（缺省）、MySQL 与 SQL Server（Oracle 在做），表结构由 ORM 按实体建出（见<a href="#建表策略">建表策略</a>）；CI 在每种库上跑全量集成测试，日常的集成测试用 SQLite 跑。不引入 EF Core 作为平行的业务数据层。</p><h2 id="支持的数据库" tabindex="-1">支持的数据库 <a class="header-anchor" href="#支持的数据库" aria-label="Permalink to “支持的数据库”">​</a></h2><table tabindex="0"><thead><tr><th>库</th><th><code>provider</code></th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>PostgreSQL</td><td><code>postgresql</code></td><td>14 及以上</td><td>缺省库</td></tr><tr><td>MySQL</td><td><code>mysql</code></td><td>8.0.13 及以上，字符集 utf8mb4</td><td>软删除实体的唯一索引是函数索引，8.0.13 起才有</td></tr><tr><td>SQL Server</td><td><code>sqlserver</code></td><td>实测 2022，库要打开 <code>READ_COMMITTED_SNAPSHOT</code></td><td>字符串列建成 <code>nvarchar</code>；缺省的读已提交是加锁读，读未提交的行要等写入方结束，在调用事务之外另开连接的读会一直等到超时。还没有表的新库由结构升级打开；已有表的库没打开即升级失败，由 DBA 执行 <code>ALTER DATABASE [库名] SET READ_COMMITTED_SNAPSHOT ON</code></td></tr><tr><td>Oracle</td><td><code>oracle</code></td><td>还不能部署</td><td>能建表，但 Oracle 把空字符串当 NULL，框架与 BasicApp 按空字符串存取的值还没有改完；库是 DBA 事先建好的用户（<code>CreateDatabase</code> 不建），字符串列建成 <code>nvarchar2</code>，最长 2000 个字符</td></tr><tr><td>SQLite</td><td><code>sqlite</code></td><td>—</td><td>只给测试用</td></tr></tbody></table><p>各库的差异由 ORM 与框架约定抹平，实体照常写：</p><ul><li>字符串列的长度按字符计。SQL Server 与 Oracle 建成 Unicode 类型（<code>nvarchar</code> / <code>nvarchar2</code>）；超过 2000 个字符的列写 <code>[LongText]</code>（Oracle 的 <code>nvarchar2</code> 装不下），长文本列不能进索引。</li><li>索引键不超过 MySQL 的 3072 字节（utf8mb4 每字符 4 字节）与 SQL Server 的 1700 字节（每字符 2 字节）：单列字符串索引最长 768 个字符，组合索引按各列之和算。集成测试 <code>ColumnWidthTests</code> 逐个核对全部实体。</li><li>日期时间列精度到微秒（MySQL <code>datetime(6)</code>、Oracle <code>timestamp(6)</code>）。</li><li>软删除实体的唯一索引只约束未删除的行：PostgreSQL、SQL Server 是带条件的索引，MySQL 与 Oracle 是函数索引；可空列为空的行不参与唯一，各库一致。</li><li>关键字搜索（<code>Contains</code> / <code>StartsWith</code> / <code>EndsWith</code>）按字面匹配，大小写照各库自己的规则：PostgreSQL 与 Oracle 区分大小写，MySQL 与 SQL Server 按库的排序规则（缺省不区分），SQLite 只对 ASCII 字母不区分。</li></ul><h2 id="平台库连接" tabindex="-1">平台库连接 <a class="header-anchor" href="#平台库连接" aria-label="Permalink to “平台库连接”">​</a></h2><p>连接写在框架的服务绑定 <code>XiHan:Bindings:db</code>：</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;XiHan&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Bindings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;db&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;connection:relational&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Host=&lt;主机&gt;;Port=5432;Database=&lt;库名&gt;;Username=&lt;用户&gt;;Password=&lt;密码&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;postgresql&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>数据库是启动硬要求：绑定缺失或为空即 <code>RUNTIME_VALIDATION_001</code> 中断启动，不回退到任何内存实现。</li><li><code>provider</code> 不写即 <code>postgresql</code>（也认 <code>postgres</code> / <code>pgsql</code> / <code>npgsql</code>），另认 <code>mysql</code>、<code>sqlserver</code>（<code>mssql</code>）、<code>oracle</code>、<code>sqlite</code>；写了别的即 <code>RUNTIME_VALIDATION_002</code>。</li><li>不提交真实连接串：<code>appsettings.json</code> 不写绑定，本机开发写在 <code>appsettings.Development.json</code>，部署用环境变量 <code>XiHan__Bindings__db__value</code> 或 Kubernetes Service Binding。</li><li>语句超时 <code>XiHan:Persistence:SqlSugar:CommandTimeoutSeconds</code>（缺省 300 秒）。</li></ul><h2 id="从库与-sql-日志" tabindex="-1">从库与 SQL 日志 <a class="header-anchor" href="#从库与-sql-日志" aria-label="Permalink to “从库与 SQL 日志”">​</a></h2><p><code>BasicApp:Database</code> 只管平台库：</p><table tabindex="0"><thead><tr><th>键</th><th>缺省</th><th>说明</th></tr></thead><tbody><tr><td><code>Replicas</code></td><td>不配</td><td>平台库的从库列表，每项 <code>ConnectionString</code> 必填、<code>HitRate</code> 是读权重。配了之后只读工作单元读从库，会写的工作单元读写都走主库</td></tr><tr><td><code>LogSql</code></td><td><code>false</code></td><td>记录每条 SQL（只记语句，不记参数值），只在排查时打开</td></tr><tr><td><code>LogSqlErrors</code></td><td><code>true</code></td><td>记录执行出错的 SQL</td></tr><tr><td><code>LogSlowSql</code></td><td><code>true</code></td><td>记录慢 SQL</td></tr><tr><td><code>SlowSqlThresholdMilliseconds</code></td><td><code>1000</code></td><td>慢 SQL 阈值</td></tr></tbody></table><p>从库只给平台库，独立库租户读写都走它自己的库。从库的缺省权重、健康探测、摘除与恢复在 <code>XiHan:Persistence:SqlSugar:Replicas</code>。决定授权的读取（会话门禁、角色指派、权限规则、访问策略等）经 <code>StoreScope.ReadPrimaryAsync</code> 钉在主库，不读落后的从库。SQL 日志的类别是 <code>XiHan.BasicApp.Sql</code>。</p><h2 id="方式一回调-sqlsugarruntime" tabindex="-1">方式一回调：<code>SqlSugarRuntime</code> <a class="header-anchor" href="#方式一回调-sqlsugarruntime" aria-label="Permalink to “方式一回调：SqlSugarRuntime”">​</a></h2><p>宿主以 <code>new SqlSugarPersistenceFeature(SqlSugarRuntime.ConfigureWith(configuration)) { DiffLog = DiffLogBuffer.IsLogged }</code> 装配持久化。回调对默认连接调用一次，带分片的调用再对 <code>shard</code> 连接调用一次：</p><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>库类型与连接串</td><td>读绑定 <code>db</code>（分片连接由框架按租户目录推出）</td></tr><tr><td>命名约定</td><td>只给框架的数据库记录：表名、列名 snake_case（<code>AuditRecord</code> → <code>audit_record</code>）；BasicApp 的实体显式写 <code>[SugarTable]</code> / <code>[SugarColumn]</code>，不经这条约定</td></tr><tr><td>操作人</td><td><code>AopEvents.DataExecuting</code> 填 <code>CreatedBy</code> / <code>ModifiedBy</code> / <code>DeletedBy</code></td></tr><tr><td>字符串缺省长度</td><td>框架记录里没有 <code>[LongText]</code> / <code>[StringLength]</code> / <code>[MaxLength]</code> 的字符串列一律 <code>varchar(512)</code>；BasicApp 的实体在 <code>[SugarColumn]</code> 里写长度</td></tr><tr><td>建表只增不改</td><td>已有的表不删列、不改列：SqlSugar 缺省会删掉实体里没有的列、按实体改已有列的类型、长度与可空，正式库上会丢数据或改写大表</td></tr><tr><td>差异日志</td><td>全审计实体的写入带差异事件，供数据变更日志使用；标了 <code>[DiffLogIgnored]</code> 的实体除外</td></tr><tr><td>从库与 SQL 日志</td><td>按 <code>BasicApp:Database</code> 挂上</td></tr></tbody></table><p>框架随后施加协议约定：主键、并发戳（长度 32）、软删除、租户列、<code>DateTimeOffset</code> 按 UTC 往返、日期时间列精度、SQL Server 与 Oracle 的 Unicode 字符串列、可空列。</p><h2 id="多库-默认连接与租户分片" tabindex="-1">多库：默认连接与租户分片 <a class="header-anchor" href="#多库-默认连接与租户分片" aria-label="Permalink to “多库：默认连接与租户分片”">​</a></h2><p>作用域客户端带两个连接：<code>default</code>（平台库）与 <code>shard</code>（带分片的租户调用才有）。框架按顺序决定实体落点：</p><ol><li>实体带 <code>[Tenant(configId)]</code> 的，落指定的连接；</li><li>实现 <code>IMultiTenant</code> 且调用有 <code>shard</code> 连接的，落分片连接；</li><li>其余落默认连接。</li></ol><p>共库（字段隔离）的租户调用没有 <code>shard</code> 连接，租户库实体与平台库同库、靠 <code>tenant_id</code> 过滤。独立库租户的连接串存在租户目录（<code>TenantRecord</code> 的 <code>ConnectionString</code> / <code>DatabaseProvider</code> 属性），以 <code>ISecretProtector</code> 密文保存；框架按租户目录建分片连接，Runtime 的 <code>ProtectedTenantShardResolver</code> 解密，解不开即 <code>RUNTIME_UNAVAILABLE_004</code>，不降级为共库。</p><div class="warning custom-block"><p class="custom-block-title">跨库事务不是两阶段提交</p><p>工作单元在第一次写入时开事务，之后首次取用的连接再补开；提交与回滚逐连接进行，是顺序提交：第二个连接提交失败时第一个已经提交。需要严格原子的写入放在同一个库里。租户开通只写平台库（租户与框架租户目录同一个工作单元）；独立库的建库建表是单独的操作 <code>tenants.initialize-database</code>，结果写回租户，失败可改连接后重试。</p></div><h2 id="数据访问" tabindex="-1">数据访问 <a class="header-anchor" href="#数据访问" aria-label="Permalink to “数据访问”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>用什么</th><th>约束</th></tr></thead><tbody><tr><td>按 ID 取、按规约列、计数、增删改、批量</td><td><code>IRepository&lt;TEntity, Guid&gt;</code>（Feature 里 <code>AddGeneratedRepositories()</code> 登记）</td><td>自动处理租户、软删除、并发戳、时间；<code>EntityQuery</code> 的 <code>Take</code> 只收 1–1000</td></tr><tr><td>分页、投影、联表、聚合</td><td>包内 <code>Queries/</code>，用 <code>ISqlSugarClient</code></td><td>必须以 <code>TenantScopedQuery.For&lt;T&gt;(context)</code> 或 <code>For&lt;T&gt;(client, context)</code> 起手（按落点取连接，补软删除与租户条件）；平台库里分侧的实体再接 <code>OwnedByCurrentTenantOrPlatform(context)</code> 或 <code>OwnedByCurrentTenant(context)</code></td></tr><tr><td>平台一侧的租户库实体</td><td>Runtime 的 <code>SideRows</code></td><td>框架仓储要求调用带租户；平台一侧的行（<code>platform</code>）经它按侧读写，写之前开事务</td></tr><tr><td>按月分表的日志</td><td>仓储按 <code>[SplitTable(SplitType.Month)]</code> 自动走分表入口，<code>EntityQuery&lt;T&gt;.Within(from, to)</code> 限定扫描的表；<code>Queries/</code> 里用 <code>.SplitTable(from, to)</code></td><td>不给时间范围即扫全部分表</td></tr><tr><td>独立于调用事务的读写</td><td><code>Runtime.Persistence.StoreScope.ReadAsync</code> / <code>ReadPrimaryAsync</code> / <code>WriteAsync</code></td><td>失败计数、会话门禁、读穿缓存的加载</td></tr><tr><td>后台对租户库的工作</td><td>框架 <code>TenantShardScope</code> 或 Contracts 的 <code>ITenantScopeRunner</code></td><td>在自建作用域里按租户绑定分片</td></tr></tbody></table><p>框架没有全局查询过滤器：直接用 <code>ISqlSugarClient</code> 而不经 <code>TenantScopedQuery</code> 起手，就会漏掉租户与软删除条件。直接用客户端写入（<code>Insertable</code> 等）之前要先调 <code>SqlSugarUnitOfWork.EnsureTransactionAsync</code>，写入才在本次调用的事务里。</p><p>只读操作（动词 <code>get</code> / <code>list</code> 或声明 <code>ReadOnly = true</code>）跑在只读工作单元里，写入即 500 <code>PERSISTENCE_UNEXPECTED_001</code>；要补建的行放到写操作里建，读路径缺行按缺省值读。</p><h2 id="建表策略" tabindex="-1">建表策略 <a class="header-anchor" href="#建表策略" aria-label="Permalink to “建表策略”">​</a></h2><table tabindex="0"><thead><tr><th>环境</th><th>方式</th></tr></thead><tbody><tr><td>开发</td><td><code>XiHan:Persistence:SqlSugar:InitTables</code> 为 <code>true</code>（<code>appsettings.Development.json</code> 已打开）：启动时按已登记的实体建缺表、加缺列，再补建部分唯一索引</td></tr><tr><td>正式</td><td>表结构升级器在启动时执行：新库按实体建全部表；已有库先执行比台账新的升级脚本，再按实体补缺的表与列，见<a href="./upgrade">表结构升级</a></td></tr></tbody></table><p>两条路径都只建缺表、加缺列，不删、不改已有的列。给已有行的表新增非可空列时：数值、枚举、布尔、<code>Guid</code> 列在 PostgreSQL 上按 CLR 缺省值回填；非可空的字符串与日期时间列不受支持，应在实体里声明成可空，或写升级脚本先加列并回填。</p><h2 id="测试库" tabindex="-1">测试库 <a class="header-anchor" href="#测试库" aria-label="Permalink to “测试库”">​</a></h2><table tabindex="0"><thead><tr><th>用例</th><th>库</th></tr></thead><tbody><tr><td>绝大多数集成测试</td><td>SQLite 临时库，经 <code>BasicAppTestServer</code> 走完整管道</td></tr><tr><td>PostgreSQL 用例（两库冒烟、从库读主库、并发发号、Provider 一致性、表结构升级等）</td><td>读环境变量 <code>XIHAN_TEST_POSTGRES</code>（服务器级连接串，不含库名），测试自建临时库；没设置即跳过</td></tr><tr><td>整套换一种库跑</td><td>环境变量 <code>XIHAN_TEST_DB</code> 设为 <code>postgresql</code>、<code>mysql</code>、<code>sqlserver</code> 或 <code>oracle</code>，每个用例在 <code>XIHAN_TEST_POSTGRES</code>、<code>XIHAN_TEST_MYSQL</code>、<code>XIHAN_TEST_SQLSERVER</code>、<code>XIHAN_TEST_ORACLE</code> 指向的服务器上建临时库（Oracle 是临时用户，连接账号要能建用户）；选了库却没配服务器即失败。直接用 SQLite 语句准备数据的用例固定在 SQLite 上</td></tr></tbody></table><p>CI（<code>.github/workflows/ci.yml</code>）的主作业起 <code>postgres:17-alpine</code> 服务并设置 <code>XIHAN_TEST_POSTGRES</code>；另有一组作业按库各跑一遍集成测试（PostgreSQL 17、MySQL 8.4、SQL Server 2022），测试库关掉刷盘以缩短建表时间。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./data-model">数据模型</a> · <a href="./upgrade">表结构升级</a> · <a href="./multi-tenancy">多租户 SaaS</a></li></ul>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};